/**
 * Test Case: Invalid Login
 *
 * Tags: @master @regression @web
 *
 * Steps:
 * 1) Navigate to My Account -> Login
 * 2) Log in with random (non-existent) credentials
 * 3) Verify the warning message and that the user is not authenticated
 */

// Generated by GitHub Copilot - Nov-23-2026
import { test, expect } from '../../fixtures/pageFixtures';
import { RandomDataUtil } from '../../utils/dataGenerator';

test('Invalid user login test @master @regression @web', async ({ homePage, loginPage }) => {
    const email = RandomDataUtil.getEmail();
    const password = RandomDataUtil.getPassword();

    await test.step('1) Navigate to the login page', async () => {
        await homePage.clickMyAccount();
        await homePage.clickLogin();
        expect(await loginPage.isLoginPageExists()).toBeTruthy();
    });

    await test.step('2) Log in with invalid credentials', async () => {
        await loginPage.login(email, password);
    });

    await test.step('3) Verify the login is rejected', async () => {
        const errorMessage = await loginPage.getLoginErrorMessage();
        expect(errorMessage).toContain('Warning: No match for E-Mail Address and/or Password.');

        // Still on the login page and the account menu only offers guest options.
        expect(await loginPage.isLoginPageExists()).toBeTruthy();
        await homePage.clickMyAccount();
        expect(await homePage.isLoginOptionExists()).toBeTruthy();
        expect(await homePage.isLogoutOptionExists()).toBeFalsy();
    });

    console.log('✅ ✔️ Invalid login rejected as expected!');
});
